class ArcamFmjFlowHandler(ConfigFlow, domain=DOMAIN):
    """Handle config flow."""

    VERSION = 1

    host: str
    port: int

    async def _async_set_unique_id_and_update(
        self, host: str, port: int, uuid: str
    ) -> None:
